pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        c.seedMarket(1e18);
        address user = address(0x1234);
        vm.prank(user);
        c.getFreeKilo();
        vm.prank(user);
        c.collectDrugs(address(0));
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();
        vm.prank(user);
        c.sellDrugs();
        uint256 marketDrugsAfter = c.marketDrugs();
        assertTrue(marketDrugsAfter > 1e18);
    }
}
